import json
from dataclasses import dataclass


@dataclass(frozen=True)
class Entry:
    """A line from our own ledger."""

    id: str
    date: str
    description: str
    amount_cents: int


@dataclass(frozen=True)
class StatementLine:
    """A line from the bank statement we are reconciling against."""

    ref: str
